 function resultForm(testId,variantId){const t=db().workshopTests?.find(t=>t.id===testId&&t.clientId===brandId),v=t?.variants.find(v=>v.id===variantId);if(!v)return;modal('Registrar resultados',`<form id="ecom-workshop-result" data-test="${esc(testId)}" data-variant="${esc(variantId)}" class="form-stack"><p>${esc(v.title)} · ${esc(v.hook)}</p><label>Fuente<input name="source" required maxlength="1000" placeholder="Meta Ads · nombre o ID del anuncio"></label><div class="two-fields"><label>Desde<input type="date" name="from" required></label><label>Hasta<input type="date" name="to" required></label></div><label>Contexto de la campaña<textarea name="context" required maxlength="4000" placeholder="Objetivo, público, ubicaciones y ventana de atribución"></textarea></label><div class="two-fields">${[['impressions','Impresiones'],['clicks','Clics'],['conversions','Conversiones'],['spend','Inversión']].map(([k,label])=>`<label>${label}<input type="number" name="${k}" min="0" step="${k==='spend'?'.01':'1'}" placeholder="Sin dato"></label>`).join('')}</div><label>Moneda<select name="currency"><option>EUR</option><option>USD</option><option>GBP</option></select></label><p class="micro">Deja vacío lo que no sepas. Cada registro se conserva por separado; no sumamos periodos que puedan solaparse.</p><button class="btn primary" type="submit">Guardar resultados</button></form>`,true);keepModalDraft('ecom-workshop-result');}
