 async function start(text='',pieceId){const r=await post('/api/conversations',{clientId:brandId,text,pieceId});cid=r.conversationId;pendingPieceId=pieceId||null;rememberThread();return cid;}
 async function showAssociation(){modal('Chats de tus piezas',`<p>Cada pieza tiene un único chat.</p><div class="scope-piece-menu">${pieces().map(p=>`<button class="scope-piece-option" data-ecom="focus-piece" data-id="${esc(p.id)}">${icon('film')}<span><strong>${esc(p.title)}</strong><small>Abrir su chat</small></span>${icon('arrow')}</button>`).join('')}</div><button class="text-btn" data-ecom="new-piece-draft">Empezar otra pieza ${icon('arrow')}</button>`);}
