 function archivedChats(){const archived=db().conversations.filter(c=>c.clientId===brandId&&c.archivedAt);modal('Historial de conversaciones',`<p class="micro">Las conversaciones retiradas conservan sus mensajes y las decisiones de las piezas.</p>${archived.map(c=>`<div class="thread-row"><button class="thread-link" data-ecom="read-archived" data-id="${esc(c.id)}">${esc(c.title)}</button><button class="text-btn" data-ecom="restore-chat" data-id="${esc(c.id)}">Restaurar</button></div>`).join('')||'<p>No hay conversaciones retiradas.</p>'}`);}
 function draftIdea(value,{free=false}={}){if(free){cid=null;pendingPieceId=null;rememberThread();}const existing=store.get(key());if(!existing.includes(value))store.set(key(),existing?existing+'\n\n'+value:value);b.closeModal();b.set({view:'conversation'});b.render();$('#ecom-input')?.focus();}
 function memoryMarkup(memory){if(!memory)return '<p class="muted">Esta conversación aún no tiene una pieza vinculada.</p>';const record=(r)=>`<article class="memory-record"><div><span class="eyebrow">${esc(({decision:'Decisión',pending:'Pendiente',handoff:'Para continuar',learning:'Aprendizaje',editing:'Para edición',direction:'Dirección',continuity:'Continuidad',idea:'Idea'})[r.kind]||r.kind)}</span><small>${esc(({confirmed:'Confirmado',working:'En trabajo',pending:'Pendiente',done:'Resuelto'})[r.status]||r.status||'')}</small></div><p>${esc(r.text)}</p>${r.sources?.length?`<div class="memory-sources">${[...new Set(r.sources.map(x=>x.conversationId).filter(Boolean))].map(id=>{const c=convs().find(c=>c.id===id);return c?`<button class="text-btn" data-ecom="conversation" data-id="${esc(id)}" data-piece="${esc(memory.pieceId)}" data-message="${esc((r.sources||[]).findLast(s=>s.conversationId===id)?.messageId||'')}">Ver conversación · ${esc(c.title)}</button>`:'';}).join('')}</div>`:''}</article>`;const state=memory.state||{};return `<section class="piece-memory"><span class="eyebrow">CONTEXTO COMPARTIDO DE LA PIEZA</span><h3>${esc(memory.title)}</h3><p class="micro">${state.scenes||0} escenas · ${state.selectedScenes||0} seleccionadas · ${esc(({off:'Voz en off',native:'Sonido nativo',mixed:'Voz mixta',silent:'Sin habla'})[state.audioMode]||state.audioMode||'Formato por definir')}</p><h4>Decisiones y pendientes</h4>${memory.records?.length?memory.records.map(record).join(''):'<p class="muted">Las decisiones que el agente guarde para esta pieza aparecerán aquí.</p>'}${memory.notes?.length?'<h4>Anotaciones</h4>'+memory.notes.map(record).join(''):''}<details><summary>Conversaciones de esta pieza · ${memory.conversations?.length||0}</summary><div class="thread-menu">${(memory.conversations||[]).map(c=>`<button class="thread-link" data-ecom="conversation" data-id="${esc(c.id)}" data-piece="${esc(memory.pieceId)}"><span>${esc(c.title)}</span><small>${c.primary?'Principal · ':''}${c.messageCount||0} mensajes${c.legacy?' · vínculo histórico':''}</small></button>`).join('')}</div></details>${Object.values(memory.truncated||{}).some(Boolean)?'<p class="micro">Aquí se muestra el contexto reciente. El agente puede consultar el dossier y las conversaciones completas cuando lo necesite.</p>':''}</section>`;}
 async function showContext(){const p=threadPiece();if(!cid){if(!p){showAssociation();return;}const memory=await api('/api/piece-memory?clientId='+encodeURIComponent(brandId)+'&pieceId='+encodeURIComponent(p.id));modal('Contexto de la pieza',memoryMarkup(memory),true);return;}const ctx=await api('/api/agent/context?conversationId='+encodeURIComponent(cid)),memory=p&&ctx.pieceMemory?.pieceId!==p.id?await api('/api/piece-memory?clientId='+encodeURIComponent(brandId)+'&pieceId='+encodeURIComponent(p.id)):ctx.pieceMemory;modal('Contexto y continuidad',`${memoryMarkup(memory)}<details class="context-inventory"><summary>Contexto de marca y herramientas disponibles</summary><h4>Contexto disponible para el siguiente turno</h4><ul>${ctx.loaded.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${ctx.documents.length} documentos · ${ctx.materials.length} materiales · ${ctx.pieces.length} piezas · ${ctx.method.length} documentos del método.</p><details><summary>Reglas de trabajo</summary><pre class="context-preview">${esc(ctx.rules)}</pre></details><details><summary>Contexto compartido de marca (${ctx.brand.context.length})</summary>${ctx.brand.context.map(x=>`<p><strong>${esc(x.title)}</strong> · ${esc(x.status)}<br>${esc(x.content)}</p>`).join('')||'<p>Aún no hay apuntes compartidos.</p>'}</details><details><summary>Documentos disponibles</summary>${ctx.documents.map(d=>`<p>${esc(d.name)} · se lee bajo demanda</p>`).join('')||'<p>No hay documentos todavía.</p>'}</details></details><p class="micro">Cada pieza tiene un único chat activo. Su dossier conserva las decisiones y las conversaciones anteriores como historial.</p><button class="btn secondary" data-act="nav" data-view="brands">Revisar mi marca</button>`,true);}

 async function referenceSelection(intent){const p=b.piece(),sc=b.scene();if(!p||!sc)return;const old=readTarget();if(old&&store.get(key()).trim()){toast('Conservamos la referencia del borrador. Envíalo o quita su referencia antes de cambiarla.');return;}const v=sc.versions.find(v=>v.assetId===b.get().vid)||sc.versions.find(v=>v.assetId===sc.selectedId)||sc.versions.at(-1),video=$('.preview-stage video');const target={pieceId:p.id,sceneId:sc.id,...(v?{assetId:v.assetId}:{}),...(v&&video?{time:Math.round(video.currentTime*100)/100}:{})};store.set(key()+':target',JSON.stringify(target));if(intent==='generate'&&!store.get(key()))store.set(key(),'Generemos esta escena. Concreta el prompt con la dirección y las referencias acordadas, y prepara la generación para revisar el coste.');store.set(dockKey(),'false');b.render();$('#ecom-input')?.focus();}


 async function draftPiecePrompt(value){
  const p=b.piece();if(!p||!value)return;
  if(threadPiece()?.id!==p.id)await choosePiece(p);
  const existing=store.get(key());if(!existing.includes(value))store.set(key(),existing?existing+'\n\n'+value:value);
  store.set(dockKey(),'false');b.closeModal();b.render();$('#ecom-input')?.focus({preventScroll:true});
 }
 async function setCreativeFocus(el,mode){
  const p=b.piece();if(!p)return;
  const kind=el.dataset.focusKind,id=el.dataset.focusId,roleId=el.dataset.focusRole,topic=el.dataset.focusTopic;
  const nextTarget=makeChatFocusTarget(p,{kind,id,roleId},{assets:db().assets});
  if(!nextTarget){toast('Este foco ya no está disponible. Vuelve a elegirlo en la pieza.');return;}
  if(threadPiece()?.id!==p.id)await choosePiece(p);
  let prompt='';
  if(mode==='draft'){
   if(kind==='intent')prompt=ideaPrompt(p,id);
   else if(kind==='angle')prompt=ideaPrompt(p,'angle',id);
   else if(kind==='opening')prompt=openingFocusPrompt(p,id);
   else if(kind==='role')prompt=castingPrompt(p,topic||'explore',id);
   else if(kind==='candidate')prompt=castingPrompt(p,'candidate',roleId,nextTarget.focus.details.assetId,db().assets);
   else if(kind==='step'&&id==='script')prompt=topic==='openings'?openingProposalPrompt(p):'Quiero trabajar el guion de esta pieza. Revisemos lo que está escrito y ajustemos lo que haga falta: apertura, cuerpo o cierre. Conserva el concepto y las partes que acordemos mantener; la interpretación y los tiempos se concretarán con la voz real.';
   else if(kind==='step'&&id==='casting')prompt=castingPrompt(p,topic||'roles');
  }
  const draft=prepareChatFocusDraft({text:store.get(key()),target:readTarget(),nextTarget,prompt,mode});
  if(!draft.ok){toast(draft.reason);return;}
  store.set(key(),draft.text);store.set(key()+':target',JSON.stringify(draft.target));store.set(dockKey(),'false');
  b.closeModal();b.render();$('#ecom-input')?.focus({preventScroll:true});
 }
 let creativeMutation=false,referenceUploading=false;
 async function uploadIdeaFiles(files,pieceId){
  if(referenceUploading)return;referenceUploading=true;
  let completed=0;const failures=[];
  try{for(const file of files){try{
   if(file.size>150*1024*1024)throw Error('máximo 150 MB');
   const r=await api('/api/material/upload?clientId='+encodeURIComponent(brandId)+'&pieceId='+encodeURIComponent(pieceId),{method:'POST',headers:{'X-File-Name':encodeURIComponent(file.name),'X-Reference-Title':encodeURIComponent(file.name),'X-Reference-Note':'','X-Reference-Kind':'creative'},body:file});
   if(r.state)b.set({db:r.state});completed++;
  }catch(error){failures.push(file.name+': '+error.message);}}
  b.render();toast([completed?completed+' referencia'+(completed===1?' incorporada.':'s incorporadas.'):'',...failures].filter(Boolean).join(' '));
  }finally{referenceUploading=false;}
 }
