 // Reconcile message markup in place. Text nodes survive incremental updates, so
 // selecting earlier prose and reading above the live response does not reset it.
 function patchNodes(old,fresh){
  for(const attr of [...old.attributes])if(!fresh.hasAttribute(attr.name))old.removeAttribute(attr.name);
  for(const attr of [...fresh.attributes])if(old.getAttribute(attr.name)!==attr.value)old.setAttribute(attr.name,attr.value);
  const desired=[...fresh.childNodes];desired.forEach((next,i)=>{let node=old.childNodes[i];if(!node){old.append(next);return;}if(node.nodeType!==next.nodeType||node.nodeName!==next.nodeName){old.replaceChild(next,node);return;}if(node.nodeType===Node.TEXT_NODE){const before=node.data,after=next.data;if(before===after)return;let prefix=0;while(prefix<before.length&&prefix<after.length&&before[prefix]===after[prefix])prefix++;if(prefix===before.length)node.appendData(after.slice(prefix));else{let suffix=0;while(suffix<before.length-prefix&&suffix<after.length-prefix&&before[before.length-1-suffix]===after[after.length-1-suffix])suffix++;node.replaceData(prefix,before.length-prefix-suffix,after.slice(prefix,after.length-suffix));}}else if(node.nodeType===Node.ELEMENT_NODE)patchNodes(node,next);});
  while(old.childNodes.length>desired.length)old.lastChild.remove();
 }
 function updateBody(el,value){if(!el||el._renderedText===value)return;const fresh=document.createElement('div');fresh.className=el.className;fresh.innerHTML=text(value);patchNodes(el,fresh);el._renderedText=value;const article=el.closest('.agent-message');if(article)article._messageMarkup=article.innerHTML;}
 function preserveReading(h,work){
  const selection=getSelection(),selecting=!selection?.isCollapsed&&h.contains(selection?.anchorNode);
  if(h._scrollIntent===1&&h.scrollHeight-h.scrollTop-h.clientHeight<=24)h._followTail=true;
  const pinned=!selecting&&h._followTail!==false;
  work();
  // Never write scrollTop while the reader is moving through earlier messages.
  if(pinned){h.scrollTop=h.scrollHeight;h._lastReadTop=h.scrollTop;}
 }
 function installReadingControl(h,following){
  h._followTail=following;h._lastReadTop=h.scrollTop;h._scrollIntent=0;
  const intent=direction=>{h._scrollIntent=direction;if(direction<0)h._followTail=false;else if(h.scrollHeight-h.scrollTop-h.clientHeight<=24)h._followTail=true;};
  h.addEventListener('wheel',e=>{if(e.deltaY)intent(Math.sign(e.deltaY));},{passive:true});
  let touchY=null;
  h.addEventListener('touchstart',e=>{touchY=e.touches[0]?.clientY;},{passive:true});
  h.addEventListener('touchmove',e=>{const y=e.touches[0]?.clientY;if(touchY!=null&&y!==touchY)intent(y>touchY?-1:1);touchY=y;},{passive:true});
  h.addEventListener('pointerdown',()=>{h._scrollIntent=0;});
  h.addEventListener('keydown',e=>{if(['ArrowUp','PageUp','Home'].includes(e.key))intent(-1);if(['ArrowDown','PageDown','End'].includes(e.key))intent(1);});
  h.addEventListener('scroll',()=>{const top=h.scrollTop,gap=h.scrollHeight-top-h.clientHeight;if(h._scrollIntent!==-1&&gap<=8)h._followTail=true;else if(top<h._lastReadTop-.5)h._followTail=false;h._lastReadTop=top;},{passive:true});
 }
 function changeThinkingLabel(label,value,h){
  void changeThinkingText(label,value,{reduced:reducedMotion.matches,update:work=>preserveReading(h,work)});
 }

 function primeStreams(){const c=conv(),h=$('#agent-history');if(!c||!h)return;const items=streamItems(c);for(const article of h.children){const source=items.get(article.dataset.part);if(!source)continue;const body=article.querySelector('.message-body');if(body)body._renderedText=source.text;if(source.streaming)streamStates.set(c.id+'|'+article.dataset.part,{shown:source.text,target:source.text,receivedAt:performance.now(),lastFrame:performance.now()});}}
 function animateStreams(){if(streamFrame)return;streamFrame=requestAnimationFrame(tickStreams);}
 function tickStreams(now){streamFrame=0;const c=conv(),h=$('#agent-history');if(!c||!h)return;let pending=false;preserveReading(h,()=>{for(const article of h.querySelectorAll('.agent-message.streaming')){const state=streamStates.get(c.id+'|'+article.dataset.part);if(!state||state.shown===state.target)continue;const dt=Math.min(50,Math.max(1,now-state.lastFrame));state.lastFrame=now;state.shown=advanceStream(state.shown,state.target,dt,now-state.receivedAt,reducedMotion.matches);updateBody(article.querySelector('.message-body'),state.shown);pending||=state.shown!==state.target;}});if(pending)animateStreams();}
 function refreshHistory(h,c){const tpl=document.createElement('template');tpl.innerHTML=history(c);const desired=[...tpl.content.children],keep=new Set(),items=streamItems(c),now=performance.now();preserveReading(h,()=>{desired.forEach((fresh,i)=>{const id=fresh.dataset.part||'extra-'+i;keep.add(id);fresh.dataset.part=id;let old=[...h.children].find(x=>x.dataset.part===id);const source=items.get(id);if(source){fresh.classList.toggle('streaming',source.streaming);const stateKey=c.id+'|'+id;let state=streamStates.get(stateKey);if(source.streaming){if(!state){state={shown:old?.querySelector('.message-body')?._renderedText||'',target:source.text,receivedAt:now,lastFrame:now};streamStates.set(stateKey,state);}if(state.target!==source.text){state.target=source.text;state.receivedAt=now;}if(reducedMotion.matches||!state.target.startsWith(state.shown))state.shown=state.target;fresh.querySelector('.message-body').innerHTML=text(state.shown);if(state.shown!==state.target)animateStreams();}else{streamStates.delete(stateKey);}if(!old){old=fresh;h.append(old);}else if(old._messageMarkup!==fresh.innerHTML||old.className!==fresh.className)patchNodes(old,fresh);old._messageMarkup=fresh.innerHTML;old.querySelector('.message-body')._renderedText=source.streaming?state.shown:source.text;}else if(!old){old=fresh;h.append(old);}else if(id==='working'){old.className=fresh.className;changeThinkingLabel(old.querySelector('.thinking-label'),fresh.querySelector('.thinking-label')?.textContent||'',h);}else if(old.outerHTML!==fresh.outerHTML){if(old.tagName==='FORM'&&old.id==='ecom-answer')return;const open=old.tagName==='DETAILS'&&old.open;old.innerHTML=fresh.innerHTML;old.className=fresh.className;if(open)old.open=true;}if(h.children[i]!==old)h.insertBefore(old,h.children[i]||null);});[...h.children].filter(x=>!keep.has(x.dataset.part)).forEach(x=>x.remove());});
 }

