 init:async()=>{config=await api('/api/agent/catalog');let pending=null;try{pending=JSON.parse(store.get('studio-pending-chat:'+brandId)||'null');}catch{}if(pending?.pieceId&&!pieces().some(p=>p.id===pending.pieceId))pending=null;const selection=restoreThreadSelection({piece:b.get().view==='piece'?b.piece():null,conversations:convs(),storedId:store.get('studio-cid:'+brandId)||store.get('studio-ecom-cid'),focusedPieceId:store.get('studio-focus:'+brandId+':'+(store.get('studio-cid:'+brandId)||store.get('studio-ecom-cid'))),pending});cid=selection.conversationId;pendingPieceId=selection.pendingPieceId;rememberThread();},
 afterRender(){if(b.get().view==='activity')brandSignature=activityStateKey();bindHomePreview(document);requestAnimationFrame(fitGuideScript);sidebarObserver?.disconnect();const composerForSize=$('.agent-page .agent-composer');if(composerForSize){sidebarObserver=new ResizeObserver(fitThreadList);sidebarObserver.observe(composerForSize);requestAnimationFrame(fitThreadList);}primeStreams();const el=$('#ecom-input');if(el){el.addEventListener('input',()=>store.set(el.dataset.draftKey,el.value));el.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();el.form.requestSubmit();}});if(uiMemory?.focused&&uiMemory.key===el.dataset.draftKey){el.focus({preventScroll:true});el.setSelectionRange(uiMemory.start,uiMemory.end);}else if(shouldFocusEmptyConversation(uiMemory?.conversation,conversationFocusState(el),{modalOpen:!!document.querySelector('#modal-root [aria-modal="true"]')})){el.focus({preventScroll:true});}}const h=$('#agent-history'),m=scrollMemory.get(cid||pendingPieceId||'new');if(h){h.scrollTop=m&&!m.bottom?m.top:h.scrollHeight;installReadingControl(h,!m||m.bottom);}boardSignature=JSON.stringify(b.piece());if(b.get().view==='brands'){brandSignature=brandStateKey();restoreBrandDetails();loadDocs().catch(e=>toast(e.message));}},
 refresh(){if(b.get().view==='activity'){const signature=activityStateKey();if(brandSignature!==signature){brandSignature=signature;b.render();}return true;}if(b.get().view==='workshop'){const signature=JSON.stringify([db().projects,db().workshopTests,pieces()]);if(brandSignature!==signature){brandSignature=signature;b.render();}return true;}if(b.get().view==='brands'){if(brandSignature!==brandStateKey())b.render();return true;}const nextFocus=pieceIdOf(conv());if(conv()&&nextFocus!==observedFocus){const previous=observedFocus;pendingPieceId=nextFocus;observedFocus=nextFocus;if(b.get().view==='piece'&&b.piece()?.id===previous&&nextFocus){const p=pieces().find(p=>p.id===nextFocus);if(p)b.set({pid:p.id,sid:p.scenes[0]?.id,vid:null});}rememberThread();b.render();return true;}const h=$('#agent-history');if(h&&conv()&&h.closest('.agent-main')?.dataset.conversation===cid){const active=['running','waiting'].includes(conv().jobs.at(-1)?.status),empty=!conv().messages.length&&!active;h.closest('.agent-main').classList.toggle('agent-empty',empty);if(!empty)refreshHistory(h,conv());const back=$('[data-ecom="return-piece"]');if(back)back.hidden=!threadPiece();const status=$('#agent-live-status'),job=conv().jobs.at(-1);if(status&&status.dataset.status!==job?.status){status.dataset.status=job?.status||'';status.textContent=job?.status==='completed'?'Respuesta completada.':job?.status==='waiting'?'El agente necesita tu respuesta.':'';}const title=$('.thread-title');if(title&&title.dataset.title!==conv().title){title.dataset.title=conv().title;title.innerHTML=esc(conv().title)+' '+icon('more');}const foot=$('.agent-footnote>span');if(foot)foot.textContent=['running','waiting'].includes(job?.status)?'Puedes seguir dándole indicaciones.':'Enter para enviar · Mayús + Enter para otra línea';const scope=$('.agent-scope-row');if(scope){const html=scopeMarkup({includeContext:!h.closest('.agent-docked')});if(scope.innerHTML!==html)scope.innerHTML=html;}}const links=$('#thread-links');if(links){const html=threadLinks();if(links.innerHTML!==html){links.innerHTML=html;fitThreadList();}}if(b.get().view==='piece'&&boardSignature!==JSON.stringify(b.piece())){b.refreshBoard();boardSignature=JSON.stringify(b.piece());}return !!h||b.get().view==='piece';},
